        target_repo_name_source: targetRepoNameEditedByApproach[currentMigrationApproach]
          ? "manual"
          : "auto-generated",
      },
      migration_approach_options: migrationApproachOptions.map((option) => ({
        value: option.value,
        label: option.label,
        desc: option.desc,
