    }

    if (runTests) {
      businessLogicSteps.push("Verify behavior changes against the configured test suite after refactoring");
    }

    return (
      <div style={{ display: "flex", flexDirection: "column", gap: 8, color: "#0f172a" }}>
        <div style={{ fontSize: 13, fontWeight: 700 }}>Business logic safeguards</div>
        <div style={{ fontSize: 12, lineHeight: 1.45 }}>
          {businessLogicSteps.map((item, index) => (
            <div key={index} style={{ marginBottom: index === businessLogicSteps.length - 1 ? 0 : 6 }}>
              {index + 1}. {item}
            </div>
          ))}
        </div>
      </div>
    );
  }, [repoAnalysis?.api_endpoints, runTests]);

  const formattedAnalysisElapsed = `${Math.floor(analysisElapsedSeconds / 60)
    .toString()
    .padStart(2, "0")}:${(analysisElapsedSeconds % 60).toString().padStart(2, "0")}`;

  const formattedAnalysisCompleted = `${Math.floor(analysisCompletedSeconds / 60)
    .toString()
    .padStart(2, "0")}:${(analysisCompletedSeconds % 60).toString().padStart(2, "0")}`;
  const isDiscoveryPending =
    isJavaProject !== false &&
    (analysisLoading || (step === 2 && Boolean(selectedRepo) && !repoAnalysis));

  useEffect(() => {
    if (!isDiscoveryPending) {
      return;
    }

    const startedAt = analysisStartedAtMs ?? Date.now();
    if (!analysisStartedAtMs) {
      setAnalysisStartedAtMs(startedAt);
      setAnalysisElapsedSeconds(0);
    }

    const updateElapsed = () => {
      setAnalysisElapsedSeconds(Math.max(1, Math.floor((Date.now() - startedAt) / 1000)));
    };

    updateElapsed();
    const interval = window.setInterval(updateElapsed, 1000);

    return () => window.clearInterval(interval);
  }, [isDiscoveryPending, analysisStartedAtMs, setAnalysisElapsedSeconds, setAnalysisStartedAtMs]);

  useEffect(() => {
    if (!isDiscoveryPending && analysisStartedAtMs) {
      const elapsed = Math.max(1, Math.floor((Date.now() - analysisStartedAtMs) / 1000));
      setAnalysisCompletedSeconds(elapsed);
      setAnalysisStartedAtMs(null);
    }
  }, [isDiscoveryPending, analysisStartedAtMs, setAnalysisCompletedSeconds, setAnalysisStartedAtMs]);

  useEffect(() => {
    setMigrationTimerNow(Date.now());

    if (!(step >= 5 && step <= 6 && migrationJob?.started_at)) {
      return;
    }

    if (isTerminalMigrationStatus(migrationJob.status)) {
      return;
    }

    const interval = window.setInterval(() => {
      setMigrationTimerNow(Date.now());
    }, 1000);

    return () => window.clearInterval(interval);
  }, [migrationJob?.completed_at, migrationJob?.started_at, migrationJob?.status, setMigrationTimerNow, step]);

  // Keep the progress bar aligned with the backend-reported migration phase.
  useEffect(() => {
    if (step === 5 && migrationJob) {
      const actualProgress = migrationJob.progress_percent || 0;
      if (isCompletedStatus(migrationJob.status)) {
        setAnimationProgress(100);
      } else if (isFailedStatus(migrationJob.status)) {
        setAnimationProgress(Math.min(Math.max(actualProgress, 5), 99));
      } else {
        setAnimationProgress(Math.min(Math.max(actualProgress, 5), 99));
      }
    } else if (step !== 5) {
      setAnimationProgress(0);
    }
  }, [migrationJob, migrationJob?.progress_percent, migrationJob?.status, setAnimationProgress, step]);

  useEffect(() => {
    const effectiveJobId = jobId || connectState?.jobId || readPersistedValue(WIZARD_JOB_ID_KEY) || "";
    if (step === 2 && effectiveJobId) {
      void fetchBrdMetadata(effectiveJobId);
    }
  }, [step, jobId, connectState?.jobId, fetchBrdMetadata]);

  const executeAnalysis = useCallback(
    async (isRerun = false) => {
      if (!selectedRepo) return;
      const isLocalProject = isLocalRepoRef(selectedRepo.url);
      const effectiveJobId = jobId || connectState?.jobId || readPersistedValue(WIZARD_JOB_ID_KEY) || "";
      const discoveryKey = `${selectedRepo.url}::${effectiveJobId || ""}::${currentToken || ""}`;

      if (discoveryInFlightKeyRef.current === discoveryKey && analysisLoading) {
        return;
      }

      discoveryInFlightKeyRef.current = discoveryKey;
      setAnalysisLoading(true);
      setAnalysisStartedAtMs(Date.now());
      setAnalysisElapsedSeconds(0);
      setError("");

      setDiscoveryStages([
        {
          id: "repository_map",
          label: "Repository Map",
          detail: "Scanning folders, modules, packages, and source file structure",
          status: "in_progress",
        },
        {
          id: "dependency_graph",
          label: "Dependency Graph",
          detail: "Reading declared libraries, Maven/Gradle dependencies, and build plugins",
          status: "queued",
        },
        {
          id: "preview_signals",
          label: "Preview Signals",
          detail: "Detecting Java version, frameworks, test suites, and project signals",
          status: "queued",
        },
        {
          id: "service_fit",
          label: "Service Fit",
          detail: "Evaluating architecture boundaries, Spring Boot fit, and service readiness",
          status: "queued",
        },
      ]);

      const stageTimer1 = window.setTimeout(() => {
        setDiscoveryStages((prev) =>
          prev.map((s) => {
            if (s.id === "repository_map") return { ...s, status: "complete", detail: "Repository structure mapped" };
            if (s.id === "preview_signals") return { ...s, status: "in_progress", detail: "Detecting Java version & compiler settings..." };
            return s;
          })
        );
      }, 700);

      const stageTimer2 = window.setTimeout(() => {
        setDiscoveryStages((prev) =>
          prev.map((s) => {
            if (s.id === "preview_signals") return { ...s, status: "complete", detail: "Java version identified" };
            if (s.id === "dependency_graph") return { ...s, status: "in_progress", detail: "Resolving dependencies and build plugins..." };
            return s;
          })
        );
      }, 1400);

      const stageTimer3 = window.setTimeout(() => {
        setDiscoveryStages((prev) =>
          prev.map((s) => {
